INSERT INTO public.vocabulary (id, word, ipa, part_of_speech, meaning_vi, definition_en, example_en, example_vi, synonyms, antonyms, topic, difficulty)
VALUES
('vocab-1', 'curriculum', '/kəˈrɪkjələm/', 'noun', 'chương trình giảng dạy', 'the subjects comprising a course of study in a school or college', 'The Ministry of Education is updating the national high school curriculum.', 'Bộ Giáo dục đang cập nhật chương trình giảng dạy THPT quốc gia.', ARRAY['syllabus', 'program of study'], ARRAY[]::text[], 'Education', 'medium'),
('vocab-2', 'persevere', '/ˌpɜːsɪˈvɪə(r)/', 'verb', 'kiên trì, bền chí', 'continue in a course of action even in the face of difficulty', 'Students who persevere through difficult math problems usually achieve higher scores.', 'Những học sinh kiên trì giải các bài toán khó thường đạt điểm số cao hơn.', ARRAY['persist', 'endure'], ARRAY['give up', 'quit'], 'Education', 'medium'),
('vocab-3', 'plagiarism', '/ˈpleɪdʒərɪzəm/', 'noun', 'sự đạo văn', 'taking someone else’s work and passing it off as one’s own', 'Universities use advanced software to detect plagiarism in academic essays.', 'Các trường đại học sử dụng phần mềm tiên tiến để phát hiện đạo văn trong bài luận học thuật.', ARRAY['copying', 'infringement'], ARRAY['originality'], 'Education', 'hard'),
('vocab-4', 'scholarship', '/ˈskɒləʃɪp/', 'noun', 'học bổng', 'a grant or payment made to support a student’s education', 'She was awarded a full scholarship to study abroad due to her excellent academic record.', 'Cô ấy được trao học bổng toàn phần để đi du học nhờ thành tích học tập xuất sắc.', ARRAY['grant', 'fellowship'], ARRAY[]::text[], 'Education', 'easy'),
('vocab-6', 'biodiversity', '/ˌbaɪəʊdaɪˈvɜːsəti/', 'noun', 'đa dạng sinh học', 'the variety of plant and animal life in a particular habitat', 'Protecting rainforests is crucial for preserving global biodiversity.', 'Bảo vệ rừng nhiệt đới có ý nghĩa sống còn đối với việc gìn giữ đa dạng sinh học toàn cầu.', ARRAY['ecological diversity'], ARRAY['monoculture'], 'Environment', 'medium'),
('vocab-7', 'deforestation', '/diːˌfɒrɪˈsteɪʃn/', 'noun', 'nạn phá rừng', 'the action of clearing a wide area of trees', 'Deforestation causes severe soil erosion and contributes significantly to climate change.', 'Nạn phá rừng gây xói mòn đất nghiêm trọng và góp phần lớn vào biến đổi khí hậu.', ARRAY['logging'], ARRAY['afforestation'], 'Environment', 'easy'),
('vocab-8', 'sustainable', '/səˈsteɪnəbl/', 'adjective', 'bền vững', 'able to be maintained without exhausting natural resources', 'Solar and wind energy are sustainable alternatives to fossil fuels.', 'Năng lượng mặt trời và gió là những giải pháp bền vững thay thế cho nhiên liệu hóa thạch.', ARRAY['renewable', 'eco-friendly'], ARRAY['unsustainable'], 'Environment', 'medium'),
('vocab-11', 'artificial intelligence', '/ˌɑːtɪfɪʃl ɪnˈtelɪdʒəns/', 'noun', 'trí tuệ nhân tạo', 'computer systems able to perform tasks requiring human intelligence', 'Artificial intelligence is transforming medical diagnostics and automated translation.', 'Trí tuệ nhân tạo đang làm thay đổi chẩn đoán y tế và dịch thuật tự động.', ARRAY['AI', 'machine intelligence'], ARRAY[]::text[], 'Technology', 'easy'),
('vocab-12', 'cybersecurity', '/ˈsaɪbəsɪkjʊərəti/', 'noun', 'an ninh mạng', 'the state of being protected against cyberattacks', 'Companies invest heavily in cybersecurity to safeguard sensitive user information.', 'Các công ty đầu tư mạnh vào an ninh mạng để bảo vệ thông tin người dùng nhạy cảm.', ARRAY['data protection', 'IT security'], ARRAY[]::text[], 'Technology', 'medium'),
('vocab-16', 'urbanization', '/ˌɜːbənaɪˈzeɪʃn/', 'noun', 'đô thị hóa', 'the process of making an area more urban', 'Rapid urbanization poses challenges for municipal infrastructure.', 'Đô thị hóa nhanh chóng đặt ra thách thức cho hạ tầng đô thị.', ARRAY['city growth'], ARRAY['ruralization'], 'Society', 'medium'),
('vocab-21', 'sedentary', '/ˈsedntri/', 'adjective', 'ít vận động, ngồi nhiều', 'tending to spend much time seated; somewhat inactive', 'A sedentary lifestyle is one of the leading risk factors for heart disease.', 'Lối sống ít vận động là một trong những yếu tố rủi ro hàng đầu dẫn đến bệnh tim.', ARRAY['inactive'], ARRAY['active'], 'Health', 'medium'),
('vocab-31', 'collaborate', '/kəˈlæbəreɪt/', 'verb', 'hợp tác, cộng tác', 'work jointly on an activity or project', 'Engineers collaborate with graphic designers to build intuitive user experiences.', 'Các kỹ sư hợp tác với nhà thiết kế đồ họa để xây dựng trải nghiệm người dùng trực quan.', ARRAY['cooperate', 'team up'], ARRAY['compete'], 'Work and Career', 'easy'),
('vocab-36', 'heritage', '/ˈherɪtɪdʒ/', 'noun', 'di sản', 'valued traditions or sites passed down from previous generations', 'Hoi An ancient town is recognized as a UNESCO World Cultural Heritage site.', 'Phố cổ Hội An được công nhận là Di sản Văn hóa Thế giới của UNESCO.', ARRAY['legacy', 'tradition'], ARRAY[]::text[], 'Culture', 'easy'),
('vocab-41', 'inflation', '/ɪnˈfleɪʃn/', 'noun', 'lạm phát', 'a general increase in prices and fall in purchasing value', 'Central banks raise interest rates to curb spiraling inflation.', 'Các ngân hàng trung ương tăng lãi suất nhằm kiềm chế lạm phát gia tăng.', ARRAY['price hike'], ARRAY['deflation'], 'Economy', 'easy'),
('vocab-46', 'ambiguous', '/æmˈbɪɡjuəs/', 'adjective', 'mơ hồ, đa nghĩa', 'open to more than one interpretation; having a double meaning', 'His ambiguous answer left the interview board unsure of his genuine intentions.', 'Câu trả lời mơ hồ của anh ấy khiến hội đồng phỏng vấn không chắc chắn.', ARRAY['vague', 'equivocal'], ARRAY['clear'], 'General Vocabulary', 'medium')
